export function getRandomFlavorText(type: string): FlavorText {
  if (!type || !MEDIA_FLAVOR_TEXTS[type] || MEDIA_FLAVOR_TEXTS[type].length === 0) {
    return { quote: 'A classic masterpiece.' };
  }
  const texts = MEDIA_FLAVOR_TEXTS[type];
  const selected = texts[Math.floor(Math.random() * texts.length)];
  if (typeof selected === 'string') {
    return { quote: selected };
  }
  return selected;
}
